from common import *
import pandas as pd
o=ROOT/"phase56";assert (o/"complete.json").exists();cw=np.array(json.loads((ROOT/"phase36/mixed_class_weights.json").read_text())["balanced_weights"]);rows=[];maxerr=0.;maxreset=0.;overlap=0;maxreplay=0.
for sid in [7,17,27,37]:
 obj=json.loads((o/f"s{sid:02d}.json").read_text());assert obj["matched_same_times_inputs_targets"] and obj["model_restored_exact"]
 for r in obj["rows"]:
  y=np.array(r["future_labels"]);p={k:np.array(r[k+"_probabilities"]) for k in ["cold_keep","cold_write","adapted_keep","adapted_write"]};loss={k:-np.log(v[np.arange(4),y]) for k,v in p.items()};cold=(loss["cold_keep"]-loss["cold_write"]);adapted=(loss["adapted_keep"]-loss["adapted_write"]);history=loss["cold_keep"]-loss["adapted_keep"];values=dict(cold_write_gain=cold.mean(),adapted_write_gain=adapted.mean(),change_in_write_utility=adapted.mean()-cold.mean(),history_keep_gain=history.mean(),cold_balanced_gain=(cold*cw[y]).mean(),adapted_balanced_gain=(adapted*cw[y]).mean(),history_balanced_gain=(history*cw[y]).mean());error=max(abs(float(v)-r[k]) for k,v in values.items());maxerr=max(maxerr,error);assert error<4e-6
  for prefix in ["cold","adapted"]:
   gain=int((p[prefix+"_write"].argmax(1)==y).sum())-int((p[prefix+"_keep"].argmax(1)==y).sum());assert gain==r[prefix+"_correct_gain"]
  maxreset=max(maxreset,r["source_reset_probability_error"])
  if r["old_cold_replay_error"] is not None:overlap+=1;maxreplay=max(maxreplay,r["old_cold_replay_error"])
  rows.append({k:v for k,v in r.items() if "probabilities" not in k and k!="future_labels"})
d=pd.DataFrame(rows);d.to_csv(o/"matched_pulses.csv",index=False);columns=["cold_write_gain","adapted_write_gain","change_in_write_utility","history_keep_gain","cold_balanced_gain","adapted_balanced_gain","history_balanced_gain","cold_correct_gain","adapted_correct_gain","drift","cold_aux_loss","adapted_aux_loss"];per=d.groupby(["subject","trajectory"])[columns].mean().reset_index();per["cold_accuracy_gain_pp"]=per.cold_correct_gain*25;per["adapted_accuracy_gain_pp"]=per.adapted_correct_gain*25;per.to_csv(o/"people.csv",index=False);summary=per.groupby("trajectory").mean(numeric_only=True).drop(columns="subject");summary.to_csv(o/"summary.csv");strata=d.groupby(["subject","trajectory","transition"])[columns].mean().reset_index();strata.to_csv(o/"transition_people.csv",index=False)
(o/"audit.json").write_text(json.dumps(dict(status="PASS",matched_state_rows=len(d),unique_times=len(d[["subject","t"]].drop_duplicates()),maximum_ce_recompute_error=maxerr,maximum_cold_keep_vs_stored_reset_error=maxreset,overlap_with_phase52_rows=overlap,maximum_phase52_cold_write_replay_error=maxreplay,same_input_and_labels_for_both_states=True),indent=2))
html='<!doctype html><html lang="zh"><meta charset="utf-8"><style>body{font:15px/1.7 system-ui;max-width:1300px;margin:30px auto}td,th{padding:5px;border-bottom:1px solid #ddd}</style><h1>相同时点的初始状态与累积状态</h1><p>阶段52冷启动与阶段54动态诊断采样时点不同，不能直接用两者平均值差异归因参数状态。本阶段精确匹配阶段54全部时点，固定当前元辅助头、相同当前输入及未来四窗，比较source初态与真实累积状态各自的一步WRITE-KEEP；另算累积KEEP相对sourceKEEP的历史收益。每个冷启动KEEP与保存的RESET概率核对，参数精确恢复。</p><p>只读离线机制分析，不训练或选择新方法。真实类别仅用于评分，不能据此按真实阶段边界控制在线更新。表中CE正值表示收益；change_in_write_utility是累积状态增量收益减去初态增量收益，history_keep_gain为既有历史状态的总收益。历史有益和新增写入有益是不同问题。</p>'+summary.to_html(float_format=lambda v:f"{v:.7f}")+per.to_html(index=False,float_format=lambda v:f"{v:.7f}")+'<p>所有均值先按受试者汇总；不把相邻窗口当独立样本。即使证实状态相关性，也不证明某种新的状态覆盖训练会有效。</p><a href="audit.json">独立审计</a> · <a href="protocol.json">协议</a></html>';(o/"report.html").write_text(html);print(summary.to_string());print(per.to_string(index=False))
